mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float sdHexPrism(vec3 p, vec2 h) {
  vec3 q = abs(p);
  return max(q.z - h.y, max((q.x * 0.866025 + q.y * 0.5), q.y) - h.x);
}
float map(vec3 p) {
  p.z += time * 0.8;
  vec3 q = p;
  vec2 r = vec2(1.732, 1.0);
  vec2 h = r * 0.5;
  vec2 a = mod(q.xy, r) - h;
  vec2 b = mod(q.xy - h, r) - h;
  vec2 g = dot(a, a) < dot(b, b) ? a : b;
  return sdHexPrism(vec3(g, q.z), vec2(0.48, 100.0));
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.4));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 12.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.06, 0.03, 0.01);
  if (t < 12.0) {
    vec3 pos = ro + rd * t;
    float fog = 1.0 / (1.0 + t * t * 0.04);
    vec3 amber = vec3(1.0, 0.65, 0.1) * (0.8 + 0.4 * sin(pos.z * 3.0 + time * 3.0));
    col = amber * fog;
  }
  ret = col;
}
